CREATE POLICY "Users read own avatar-creator files" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'avatar-creator' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Users insert own avatar-creator files" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'avatar-creator' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Users update own avatar-creator files" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'avatar-creator' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Users delete own avatar-creator files" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'avatar-creator' AND (storage.foldername(name))[1] = auth.uid()::text);